const fs = require('node:fs');
(async () => {
  const targets = await (await fetch('http://localhost:9224/json/list')).json();
  const target = targets.find((item) => item.type === 'page');
  if (!target?.webSocketDebuggerUrl) throw new Error('No CDP page target');
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, { once: true }); ws.addEventListener('error', reject, { once: true }); });
  let id = 0;
  const pending = new Map();
  const errors = [];
  ws.addEventListener('message', ({ data }) => {
    const message = JSON.parse(data);
    if (message.method === 'Runtime.exceptionThrown') errors.push(`exception: ${message.params.exceptionDetails.text}`);
    if (message.method === 'Runtime.consoleAPICalled' && message.params.type === 'error') errors.push(`console: ${message.params.args.map((arg) => arg.value || arg.description).join(' ')}`);
    if (message.method === 'Network.loadingFailed') errors.push(`network: ${message.params.errorText} ${message.params.requestId}`);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      message.error ? reject(new Error(message.error.message)) : resolve(message.result);
    }
  });
  const call = (method, params = {}) => new Promise((resolve, reject) => {
    const commandId = ++id;
    pending.set(commandId, { resolve, reject });
    ws.send(JSON.stringify({ id: commandId, method, params }));
  });
  const evaluate = async (expression) => {
    const result = await call('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
    if (result.exceptionDetails) throw new Error(result.exceptionDetails.text);
    return result.result.value;
  };
  const waitFor = async (expr) => evaluate(`(async()=>{const deadline=Date.now()+10000;while(Date.now()<deadline){if(${expr})return true;await new Promise(r=>setTimeout(r,100))}return false})()`);
  await call('Runtime.enable'); await call('Page.enable'); await call('Network.enable');
  await call('Page.navigate', { url: 'http://localhost:3002/' });
  if (!(await waitFor("document.readyState==='complete' && document.querySelector('[data-nav=oracle]')"))) throw new Error('Home did not load');
  await call('Page.captureScreenshot', { format: 'png' }).then((result) => fs.writeFileSync('/tmp/opencode/baseline-home.png', Buffer.from(result.data, 'base64')));
  await evaluate("document.querySelector('[data-nav=oracle]').click()");
  if (!(await waitFor("document.querySelector('#view-oracle')?.classList.contains('active')"))) throw new Error('Oracle navigation failed');
  await evaluate("(()=>{const input=document.querySelector('#chatInput');input.value='¿Cómo afecta el riego?';input.dispatchEvent(new Event('input',{bubbles:true}));document.querySelector('#chatForm').requestSubmit();return true})()");
  if (!(await waitFor("document.querySelector('#chatLog')?.innerText.includes('riego')"))) throw new Error('Oracle answer not rendered');
  const oracle = await evaluate("({answer:document.querySelector('#chatLog')?.innerText, sources:document.querySelector('#sourceCount')?.innerText})");
  await call('Page.navigate', { url: 'http://localhost:3002/bruma-botanica.html' });
  if (!(await waitFor("document.readyState==='complete' && document.querySelectorAll('#tablero button').length===8"))) throw new Error('Bruma game did not load');
  await evaluate("document.querySelector('#tablero button').click()");
  const revealed = await waitFor("document.querySelector('.memory-card.is-revealed') && document.querySelector('#gameStatus')?.innerText.includes('Revelaste')");
  await evaluate("document.querySelector('#restartButton').click()");
  const reset = await evaluate("({round:document.querySelector('#roundValue')?.innerText,score:document.querySelector('#scoreValue')?.innerText,time:document.querySelector('#timeValue')?.innerText,revealed:document.querySelectorAll('.memory-card.is-revealed').length,status:document.querySelector('#gameStatus')?.innerText})");
  await call('Page.captureScreenshot', { format: 'png' }).then((result) => fs.writeFileSync('/tmp/opencode/baseline-game.png', Buffer.from(result.data, 'base64')));
  console.log(JSON.stringify({ home: 'loaded', oracle, game: { revealed, reset }, errors }, null, 2));
  ws.close();
  if (!revealed || reset.round.trim() !== '1 / 3' || reset.revealed !== 0 || errors.length) process.exitCode = 1;
})().catch((error) => { console.error(error.stack || error); process.exitCode = 1; });
